    VALUES (s.ID_PERKIRAAN, s.ID_MODEL, s.AWAL_PEKAN_SASARAN, s.TANGGAL_PERKIRAAN, s.JUMLAH_PEKAN_PELATIHAN, s.JUMLAH_PERKIRAAN, s.BATAS_BAWAH, s.BATAS_ATAS, s.PENYESUAIAN_KALENDER, s.KETERANGAN);
